"""Per-key rate limiter using a sliding window log (Approach B).

Each key keeps a deque of timestamps for its recent allowed calls. On each
call, entries that have fallen out of the window are evicted from the front,
and the call is allowed if fewer than the key's limit entries remain.
"""

from __future__ import annotations

from collections import deque


class RateLimiter:
    def __init__(self, limit: int, window_seconds: float) -> None:
        if limit < 1:
            raise ValueError("limit must be >= 1")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be > 0")
        self._limit = limit
        self._window = float(window_seconds)
        self._logs: dict[str, deque[float]] = {}
        self._limits: dict[str, int] = {}

    # -- internals ---------------------------------------------------------

    def _limit_for(self, key: str) -> int:
        return self._limits.get(key, self._limit)

    def _evict(self, log: deque[float], now: float) -> None:
        # Drop calls that no longer fall inside (now - window, now].
        # A call made exactly ``window`` seconds ago has completed its window,
        # so it is dropped too; this is what lets a full burst recur at now == window.
        cutoff = now - self._window
        while log and log[0] <= cutoff:
            log.popleft()

    # -- public API --------------------------------------------------------

    def allow(self, key: str, now: float) -> bool:
        log = self._logs.get(key)
        if log is None:
            log = deque()
            self._logs[key] = log
        self._evict(log, now)
        if len(log) < self._limit_for(key):
            log.append(now)
            return True
        return False

    def remaining(self, key: str, now: float) -> int:
        """Calls that would currently be allowed for ``key``, without consuming one."""
        log = self._logs.get(key)
        used = 0
        if log is not None:
            self._evict(log, now)
            used = len(log)
        return max(0, self._limit_for(key) - used)

    def reset(self, key: str) -> None:
        """Forget ``key``'s recorded calls. A per-key limit override is kept."""
        self._logs.pop(key, None)

    def set_limit(self, key: str, limit: int) -> None:
        """Override the limit for ``key``; the window is unchanged."""
        if limit < 1:
            raise ValueError("limit must be >= 1")
        self._limits[key] = limit
